insert into passages (id, text, difficulty_level, b, active) values
('500212bd-ae3f-4c93-b4dd-c83502d7636c', 'The Dunning-Kruger effect, first described by psychologists David Dunning and Justin Kruger in 1999, refers to a cognitive bias in which individuals with limited competence in a particular domain overestimate their own ability, while those with genuine expertise often underestimate theirs. The researchers proposed that this asymmetry arises because the same skills required to perform well in a domain are also the skills needed to accurately assess one''s own performance in it; consequently, those who lack these skills are doubly disadvantaged, both in their competence and in their capacity to recognize that incompetence. Subsequent research has produced a more nuanced picture, suggesting that the effect may be partly attributable to statistical artifacts, such as regression to the mean, rather than a purely psychological phenomenon. Nevertheless, the core intuition behind the effect, that confidence and competence are not always correlated, continues to resonate widely and has been invoked in contexts ranging from workplace management to political discourse, sometimes with more rhetorical flourish than empirical rigor.', 5, 2.0, true),
('41817e81-621b-4990-96c9-891df1c5d053', 'Economists have long debated the relationship between income inequality and economic growth, with empirical findings often appearing contradictory depending on the time period, country, and methodology examined. Some argue that moderate inequality can spur growth by incentivizing innovation and hard work, as the prospect of substantial reward motivates individuals to take entrepreneurial risks they might otherwise avoid. Others contend that excessive inequality undermines growth over the long run by restricting access to education and credit for lower-income populations, thereby squandering human capital that could otherwise contribute productively to the economy. Cross-country studies conducted over the past two decades have generally found a negative correlation between high levels of inequality and sustained growth, particularly in developing economies, though the causal mechanisms remain contested among researchers. Some scholars caution against drawing overly strong conclusions from this correlation, noting that reverse causality is plausible: sluggish growth itself may exacerbate inequality by disproportionately harming those with the fewest resources to weather economic downturns.', 5, 2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('e627b580-93e7-44be-a577-c4e5174ccc57', 'sentence_completion', 'The diplomat''s carefully ___ language avoided offending either side of the dispute.', NULL, '[{"id": "a", "text": "calibrated"}, {"id": "c", "text": "spontaneous"}, {"id": "b", "text": "aggressive"}, {"id": "d", "text": "reckless"}]'::jsonb, 0, '{"strategy": "avoided offending either side = נמנעה מלפגוע בשני הצדדים. איזו שפה מדויקת עושה זאת?", "correct_reason": "calibrated = מכוונת/מדודה בקפידה. שפה מדודה נמנעת מפגיעה.", "options_analysis": ["נכון! calibrated = מכוונת בקפידה — מתאים לנמנעות מפגיעה", "spontaneous = ספונטני — הפוך מ''carefully''", "aggressive = תוקפני — סותר הימנעות מפגיעה", "reckless = פזיז — הפוך משפה זהירה"]}', 1.4, 2.0, 0.25, 5, 'ai', NULL, true),
('5859d52e-4be4-4856-a35a-18b886e11224', 'sentence_completion', 'The committee''s report was criticized for its ___ conclusions, which oversimplified a complex issue.', NULL, '[{"id": "d", "text": "balanced"}, {"id": "b", "text": "reductive"}, {"id": "c", "text": "nuanced"}, {"id": "a", "text": "comprehensive"}]'::jsonb, 1, '{"strategy": "oversimplified a complex issue = הפשיטה יתר על המידה. איזו מסקנה מפשטת יתר על המידה?", "correct_reason": "reductive = מצמצם/מפשט יתר על המידה.", "options_analysis": ["balanced = מאוזן — לא מסביר ביקורת על הפשטה", "נכון! reductive = מצמצם — מתאים ל''oversimplified''", "nuanced = רב-גוני — הפוך מהפשטה", "comprehensive = מקיף — הפוך מהפשטה"]}', 1.1, 2.0, 0.25, 5, 'ai', NULL, true),
('c36fe94c-1f28-433d-8eb4-dc97e8e1867b', 'sentence_completion', 'Her ___ knowledge of ancient languages made her an invaluable asset to the research team.', NULL, '[{"id": "a", "text": "limited"}, {"id": "c", "text": "superficial"}, {"id": "b", "text": "encyclopedic"}, {"id": "d", "text": "fragmentary"}]'::jsonb, 2, '{"strategy": "invaluable asset = נכס יקר ערך. איזה ידע הופך למישהו לנכס כזה?", "correct_reason": "encyclopedic = אנציקלופדי/רחב ומקיף. ידע רחב הופך למומחה יקר ערך.", "options_analysis": ["limited = מוגבל — הפוך מנכס יקר ערך", "superficial = שטחי — הפוך מ''invaluable''", "נכון! encyclopedic = רחב ומקיף — מתאים לנכס יקר ערך", "fragmentary = מקוטע — הפוך מידע רחב"]}', 1.6, 2.0, 0.25, 5, 'ai', NULL, true),
('fe9636b2-fe61-495a-bf82-677c5cdd6546', 'sentence_completion', 'The board''s ___ approval of the merger surprised analysts who had expected fierce debate.', NULL, '[{"id": "d", "text": "partial"}, {"id": "c", "text": "delayed"}, {"id": "a", "text": "contested"}, {"id": "b", "text": "unanimous"}]'::jsonb, 3, '{"strategy": "surprised analysts who expected fierce debate = הפתיע אנליסטים שציפו לוויכוח. איזה סוג אישור מפתיע במקום ויכוח?", "correct_reason": "unanimous = פה אחד. אישור פה אחד מפתיע כשציפו למחלוקת.", "options_analysis": ["partial = חלקי — לא מתאים ל''approval'' מוחלט", "delayed = מעוכב — לא מסביר הפתעה", "contested = שנוי במחלוקת — סותר את ההפתעה, זה מה שציפו לו", "נכון! unanimous = פה אחד — מפתיע לעומת הציפייה לוויכוח"]}', 1.31, 2.0, 0.25, 5, 'ai', NULL, true),
('cc483538-5acb-41fd-a3f0-8df6ce57a5d8', 'sentence_completion', 'The author''s prose, though ___ at times, ultimately conveys a profound emotional truth.', NULL, '[{"id": "c", "text": "dense"}, {"id": "a", "text": "simple"}, {"id": "d", "text": "clear"}, {"id": "b", "text": "accessible"}]'::jsonb, 0, '{"strategy": "though...at times, ultimately conveys = למרות קושי מסוים, בסוף מעביר משמעות עמוקה. ניגוד.", "correct_reason": "dense = צפוף/כבד. פרוזה כבדה עדיין יכולה להעביר אמת רגשית עמוקה.", "options_analysis": ["נכון! dense = כבד/צפוף — יוצר ניגוד הגיוני עם ההצלחה הרגשית", "simple = פשוט — לא יוצר ניגוד", "clear = בהיר — לא יוצר ניגוד עם ''ultimately''", "accessible = נגיש — לא יוצר ניגוד"]}', 1.6, 2.0, 0.25, 5, 'ai', NULL, true),
('afecb580-11cc-40df-b5e0-da931609481b', 'sentence_completion', 'The startup''s ___ expansion into new markets ultimately led to its financial downfall.', NULL, '[{"id": "b", "text": "gradual"}, {"id": "d", "text": "precipitous"}, {"id": "c", "text": "measured"}, {"id": "a", "text": "cautious"}]'::jsonb, 1, '{"strategy": "ultimately led to its financial downfall = הובילה לקריסה כלכלית. איזו הרחבה מובילה לקריסה?", "correct_reason": "precipitous = פזיז/פתאומי מדי. הרחבה פזיזה מסבירה קריסה.", "options_analysis": ["gradual = הדרגתי — פחות סביר לגרום לקריסה", "נכון! precipitous = פזיז מדי — מסביר קריסה כלכלית", "measured = מדוד — הפוך מקריסה", "cautious = זהיר — הפוך מקריסה"]}', 1.42, 2.0, 0.25, 5, 'ai', NULL, true),
('fcf7eece-095f-4407-bc2a-6bdc27ff75a7', 'sentence_completion', 'The philosopher''s argument, while logically ___, failed to account for real-world complexity.', NULL, '[{"id": "b", "text": "weak"}, {"id": "d", "text": "flawed"}, {"id": "a", "text": "coherent"}, {"id": "c", "text": "confusing"}]'::jsonb, 2, '{"strategy": "while...failed to account for = בעוד ש-...נכשל בהתחשבות ב-. ניגוד.", "correct_reason": "coherent = עקבי/הגיוני. טיעון הגיוני יכול עדיין להיכשל בהתמודדות עם מורכבות.", "options_analysis": ["weak = חלש — לא יוצר את הניגוד הנדרש", "flawed = פגום — לא יוצר ניגוד הגיוני עם ''while''", "נכון! coherent = עקבי — יוצר ניגוד: הגיוני אך לא מספיק מעשי", "confusing = מבלבל — לא יוצר ניגוד הגיוני"]}', 1.36, 2.0, 0.25, 5, 'ai', NULL, true),
('5824b76a-3f73-4f44-a350-d359a03e42ac', 'sentence_completion', 'The new regulations were ___ enough to close the loophole without stifling innovation.', NULL, '[{"id": "b", "text": "arbitrary"}, {"id": "d", "text": "excessive"}, {"id": "a", "text": "vague"}, {"id": "c", "text": "precise"}]'::jsonb, 3, '{"strategy": "close the loophole without stifling innovation = לסגור פרצה בלי לחנוק חדשנות. איזה סוג תקנות משיג איזון כזה?", "correct_reason": "precise = מדויקות. תקנות מדויקות סוגרות פרצה בלי פגיעה רחבה.", "options_analysis": ["arbitrary = שרירותיות — לא מדויקות מספיק", "excessive = מוגזמות — סביר שיחנקו חדשנות", "vague = מעורפלות — לא יעילות לסגירת פרצה", "נכון! precise = מדויקות — מאפשרות איזון בין סגירת פרצה לחדשנות"]}', 1.53, 2.0, 0.25, 5, 'ai', NULL, true),
('948a3b0a-274b-4603-97c6-d5e0f4885903', 'sentence_completion', 'The economist''s predictions proved remarkably ___, despite widespread skepticism at the time.', NULL, '[{"id": "a", "text": "prescient"}, {"id": "c", "text": "outdated"}, {"id": "b", "text": "inaccurate"}, {"id": "d", "text": "irrelevant"}]'::jsonb, 0, '{"strategy": "despite widespread skepticism = למרות ספקנות רחבה. איזו תחזית מתגלה כנכונה למרות ספק?", "correct_reason": "prescient = חזוני/צופה פני עתיד בדייקנות.", "options_analysis": ["נכון! prescient = חזוני — מתאים לתחזית שהתבררה כנכונה", "outdated = מיושנת — סותר ''proved remarkably''", "inaccurate = לא מדויקת — סותר ''remarkably'', שמרמז על הצלחה", "irrelevant = לא רלוונטית — לא מסביר הצלחה"]}', 1.2, 2.0, 0.25, 5, 'ai', NULL, true),
('28f88065-f849-41d5-a02c-609f1d6c3ba3', 'sentence_completion', 'The negotiator''s ___ style, alternating between firmness and flexibility, proved highly effective.', NULL, '[{"id": "a", "text": "predictable"}, {"id": "d", "text": "adaptive"}, {"id": "c", "text": "aggressive"}, {"id": "b", "text": "rigid"}]'::jsonb, 1, '{"strategy": "alternating between firmness and flexibility = מתחלף בין תקיפות לגמישות. איזה סגנון כזה?", "correct_reason": "adaptive = מסתגל/גמיש. סגנון שמתחלף בהתאם למצב הוא מסתגל.", "options_analysis": ["predictable = צפוי — פחות מתאים לתחלופה אסטרטגית", "נכון! adaptive = מסתגל — מתאים לסגנון שמשתנה לפי הצורך", "aggressive = תוקפני — לא מתאר את שני הצדדים (תקיפות וגמישות)", "rigid = נוקשה — סותר ''alternating''"]}', 1.02, 2.0, 0.25, 5, 'ai', NULL, true),
('bbe3fe69-004a-47a5-9134-92e9a6eb7b31', 'sentence_completion', 'The committee''s ___ handling of the crisis drew praise from even its harshest critics.', NULL, '[{"id": "c", "text": "careless"}, {"id": "d", "text": "hesitant"}, {"id": "b", "text": "adept"}, {"id": "a", "text": "chaotic"}]'::jsonb, 2, '{"strategy": "drew praise from even its harshest critics = זכה לשבח אפילו ממבקרים קשוחים. איזה טיפול ראוי לשבח כזה?", "correct_reason": "adept = מיומן/מוכשר. טיפול מיומן ראוי לשבח רחב.", "options_analysis": ["careless = חסר זהירות — הפוך משבח", "hesitant = מהוסס — פחות סביר לזכות בשבח נרחב", "נכון! adept = מיומן — מסביר שבח נרחב אפילו ממבקרים", "chaotic = כאוטי — הפוך משבח"]}', 1.52, 2.0, 0.25, 5, 'ai', NULL, true),
('875118fd-3c4c-411c-b962-a5b727f7da41', 'sentence_completion', 'The novel''s ___ narrative structure, jumping between timelines, initially confused readers but ultimately enriched the story.', NULL, '[{"id": "d", "text": "conventional"}, {"id": "c", "text": "linear"}, {"id": "a", "text": "predictable"}, {"id": "b", "text": "fragmented"}]'::jsonb, 3, '{"strategy": "jumping between timelines = קופצת בין ציר זמנים. איזה מבנה עלילה עושה זאת?", "correct_reason": "fragmented = מקוטע. מבנה מקוטע מזוהה עם קפיצות בזמן.", "options_analysis": ["conventional = קונבנציונלי — הפוך ממבנה יוצא דופן", "linear = ליניארי — הפוך מ''jumping between timelines''", "predictable = צפוי — לא מסביר בלבול ראשוני", "נכון! fragmented = מקוטע — מתאים למבנה שקופץ בין תקופות"]}', 1.58, 2.0, 0.25, 5, 'ai', NULL, true),
('7434d139-d998-4c2b-ae7f-bdf1204a5009', 'restatement', 'It was not until decades later that the full extent of the cover-up came to light.', NULL, '[{"id": "d", "text": "Decades passed before the full extent of the cover-up became known."}, {"id": "b", "text": "The full extent of the cover-up was known immediately."}, {"id": "a", "text": "The cover-up came to light before it even began."}, {"id": "c", "text": "The cover-up was never fully revealed."}]'::jsonb, 0, '{"strategy": "not until decades later = לא עד עשרות שנים לאחר מכן. תנאי הכרחי מתהפך.", "correct_reason": "אותו תנאי בדיוק: חלפו עשרות שנים לפני שנחשף.", "options_analysis": ["נכון! אותו תנאי בדיוק: חלפו עשרות שנים לפני החשיפה", "סותר ''not until decades later'' — לא נודע מיד", "סותר לגמרי — הכיסוי קדם לחשיפה, לא להפך", "סותר ''came to light'' — זה כן נחשף בסוף"]}', 1.56, 2.0, 0.25, 5, 'ai', NULL, true),
('3ab2280b-baa5-4567-93d6-be68f0094432', 'restatement', 'Seldom has a policy generated as much controversy as this one has.', NULL, '[{"id": "d", "text": "Policies rarely generate any controversy at all."}, {"id": "a", "text": "This policy has generated an unusually high amount of controversy."}, {"id": "c", "text": "This policy is far less controversial than most others."}, {"id": "b", "text": "This policy has generated no controversy at all."}]'::jsonb, 1, '{"strategy": "seldom has X generated as much as this = נדיר שמדיניות עוררה כמו זו. יוצא דופן.", "correct_reason": "אותה משמעות בדיוק: מחלוקת חריגה בהיקפה.", "options_analysis": ["הכללה שגויה — המקור מדבר על מדיניות ספציפית זו", "נכון! אותה משמעות בדיוק: מחלוקת יוצאת דופן בהיקפה", "הפוך גמור — המדיניות הזו שנויה במחלוקת יותר מהרגיל", "סותר ''as much controversy'' — יש מחלוקת רבה"]}', 1.44, 2.0, 0.25, 5, 'ai', NULL, true),
('a534d1af-ef6a-49f9-a68f-7badbde5e6a8', 'restatement', 'For all its flaws, the proposal represents a meaningful step forward.', NULL, '[{"id": "b", "text": "Because of its flaws, the proposal was rejected entirely."}, {"id": "c", "text": "The proposal has no flaws whatsoever."}, {"id": "a", "text": "Despite its flaws, the proposal represents a meaningful step forward."}, {"id": "d", "text": "The proposal represents a step backward due to its flaws."}]'::jsonb, 2, '{"strategy": "for all its flaws...represents = על אף פגמיה...מהווה. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["לא נאמר במקור שנדחתה", "סותר ''for all its flaws'' — יש לה פגמים", "נכון! אותה משמעות בדיוק: למרות הפגמים, זהו צעד משמעותי קדימה", "הפוך — ''step forward'' סותר ''step backward''"]}', 1.37, 2.0, 0.25, 5, 'ai', NULL, true),
('4f980485-9fa8-446d-88ab-42498dddfd37', 'restatement', 'What the report lacks in detail, it makes up for in clarity.', NULL, '[{"id": "c", "text": "The report lacks both detail and clarity."}, {"id": "a", "text": "The report is detailed but lacks any clarity."}, {"id": "b", "text": "The report is both detailed and unclear."}, {"id": "d", "text": "Although the report is not very detailed, it is very clear."}]'::jsonb, 3, '{"strategy": "what X lacks in A, it makes up for in B = מה שחסר ב-A, מפוצה ב-B.", "correct_reason": "אותה משמעות בדיוק: פחות פרטים, אך בהירות רבה.", "options_analysis": ["סותר את שני חלקי המשפט", "הפוך — ''lacks any clarity'' סותר ''makes up for in clarity''", "סותר ''lacks in detail'' — הדוח לא מפורט מאוד", "נכון! אותה משמעות בדיוק: פחות פרטים, פיצוי בבהירות"]}', 1.02, 2.0, 0.25, 5, 'ai', NULL, true),
('3fd038d0-211d-4407-827c-8048593f6426', 'restatement', 'Nothing short of a complete overhaul will solve the system''s deep-rooted problems.', NULL, '[{"id": "c", "text": "Only a complete overhaul can solve the system''s deep-rooted problems."}, {"id": "b", "text": "The system''s problems cannot be solved under any circumstances."}, {"id": "d", "text": "A complete overhaul is unnecessary to solve the system''s problems."}, {"id": "a", "text": "Minor adjustments will be enough to solve the system''s problems."}]'::jsonb, 0, '{"strategy": "nothing short of X will = רק X יפתור. תנאי הכרחי בניסוח שלילי.", "correct_reason": "אותו תנאי הכרחי בדיוק: רק שיפוץ מלא יפתור.", "options_analysis": ["נכון! אותו תנאי הכרחי בדיוק: רק שיפוץ מלא יפתור", "סותר לגמרי — יש פתרון אפשרי (שיפוץ מלא)", "סותר ''nothing short of a complete overhaul''", "סותר ''nothing short of'' — התאמות קטנות לא יספיקו"]}', 1.16, 2.0, 0.25, 5, 'ai', NULL, true),
('1dabd8f0-6a18-4447-a241-7764fc715505', 'restatement', 'The committee''s recommendations, though well-intentioned, proved impractical in application.', NULL, '[{"id": "b", "text": "The committee had no intentions when making its recommendations."}, {"id": "a", "text": "Despite good intentions, the recommendations turned out to be impractical."}, {"id": "c", "text": "The recommendations were poorly intentioned and impractical."}, {"id": "d", "text": "The recommendations were both well-intentioned and highly practical."}]'::jsonb, 1, '{"strategy": "though well-intentioned...impractical = למרות כוונות טובות, לא מעשי. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר ''though well-intentioned'' — היו כוונות", "נכון! אותה משמעות בדיוק: כוונות טובות אך יישום לא מעשי", "סותר ''well-intentioned''", "סותר ''proved impractical''"]}', 1.03, 2.0, 0.25, 5, 'ai', NULL, true),
('d8163ff0-ce17-4b39-8cec-07e690fa74d8', 'restatement', 'Not for a moment did the survivors doubt that rescue would come.', NULL, '[{"id": "d", "text": "The survivors doubted rescue would ever come."}, {"id": "a", "text": "Rescue came before the survivors had any doubts."}, {"id": "c", "text": "The survivors were completely confident that rescue would come."}, {"id": "b", "text": "The survivors gave up hope of being rescued."}]'::jsonb, 2, '{"strategy": "not for a moment did...doubt = אף לרגע לא פקפקו. שלילה כפולה = ביטחון מוחלט.", "correct_reason": "אותה משמעות בדיוק: ביטחון מלא לאורך כל הזמן.", "options_analysis": ["הפוך גמור — ''not for a moment doubt'' = לא היה ספק כלל", "לא נאמר במקור התייחסות לתזמון כזה", "נכון! אותה משמעות בדיוק: ביטחון מוחלט שהחילוץ יגיע", "סותר לגמרי — הם מעולם לא פקפקו"]}', 1.01, 2.0, 0.25, 5, 'ai', NULL, true),
('ba8e91e8-279e-4dd8-9e03-ced6e3ad1122', 'restatement', 'Far from resolving the dispute, the mediator''s intervention only intensified it.', NULL, '[{"id": "c", "text": "The mediator refused to intervene in the dispute at all."}, {"id": "b", "text": "The mediator''s intervention successfully resolved the dispute."}, {"id": "d", "text": "The dispute ended before the mediator could intervene."}, {"id": "a", "text": "The mediator''s intervention made the dispute worse, not better."}]'::jsonb, 3, '{"strategy": "far from resolving...only intensified = רחוק מפתרון...רק החריף. ניגוד קיצוני.", "correct_reason": "אותה משמעות בדיוק: החמרה במקום פתרון.", "options_analysis": ["סותר ''intervention'' — הוא כן התערב", "סותר ''far from resolving'' — הגישור לא פתר את הסכסוך", "סותר את הרצף שמתואר במקור", "נכון! אותה משמעות בדיוק: התערבות שהחריפה את המצב"]}', 1.15, 2.0, 0.25, 5, 'ai', NULL, true),
('1ea789bb-0065-4d57-ae14-f73562370ab6', 'restatement', 'So entrenched was the corruption that even reformers struggled to make progress.', NULL, '[{"id": "c", "text": "The corruption was so deeply rooted that reformers found it hard to make progress."}, {"id": "a", "text": "There was no corruption for reformers to address."}, {"id": "b", "text": "Reformers made rapid progress against the corruption."}, {"id": "d", "text": "The corruption disappeared as soon as reformers arrived."}]'::jsonb, 0, '{"strategy": "so entrenched...that struggled = כה מושרש...עד שהתקשו. תוצאה קיצונית.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: שחיתות מושרשת הקשתה על התקדמות", "סותר ''the corruption'' — היא כן הייתה קיימת", "הפוך — ''struggled to make progress'' סותר התקדמות מהירה", "סותר לגמרי — היא נותרה מושרשת, לא נעלמה"]}', 1.19, 2.0, 0.25, 5, 'ai', NULL, true),
('4c7283ab-4f67-4bc4-b5b2-481c411e6aa2', 'restatement', 'Much as she admired his ambition, she could not overlook his recklessness.', NULL, '[{"id": "c", "text": "She had no admiration for him at all."}, {"id": "b", "text": "She admired his ambition but was still bothered by his recklessness."}, {"id": "a", "text": "She admired his recklessness more than his ambition."}, {"id": "d", "text": "She overlooked his recklessness because she admired his ambition."}]'::jsonb, 1, '{"strategy": "much as she admired...could not overlook = אף שהעריצה...לא הצליחה להתעלם. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר ''much as she admired'' — היא כן העריצה", "נכון! אותה משמעות בדיוק: העריצה אך עדיין הוטרדה מהפזיזות", "הפוך — במקור הפזיזות היא הבעיה, לא מושא הערצה", "סותר ''could not overlook'' — היא לא הצליחה להתעלם"]}', 1.33, 2.0, 0.25, 5, 'ai', NULL, true),
('22f4dc2c-0184-4a8d-a15f-2d71f8107d3d', 'restatement', 'The evidence, compelling though it seemed, was ultimately deemed insufficient by the court.', NULL, '[{"id": "d", "text": "The court found the evidence entirely conclusive."}, {"id": "b", "text": "The court refused to examine the evidence."}, {"id": "c", "text": "Although the evidence appeared convincing, the court ruled it was not enough."}, {"id": "a", "text": "The evidence was weak from the very beginning."}]'::jsonb, 2, '{"strategy": "compelling though it seemed...insufficient = משכנעת לכאורה...לא מספיקה בסוף. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר ''deemed insufficient''", "סותר לגמרי — בית המשפט כן בחן את הראיות", "נכון! אותה משמעות בדיוק: נראתה משכנעת אך נפסלה כלא מספיקה", "סותר ''compelling though it seemed'' — נראתה משכנעת"]}', 1.51, 2.0, 0.25, 5, 'ai', NULL, true),
('9894e823-d4a4-4097-8425-f8aa44c18b36', 'reading_comprehension', 'What is the main idea of the passage?', '500212bd-ae3f-4c93-b4dd-c83502d7636c', '[{"id": "b", "text": "Statistical artifacts fully explain why some people overestimate their abilities"}, {"id": "c", "text": "David Dunning and Justin Kruger disproved all earlier theories of cognitive bias"}, {"id": "a", "text": "Incompetent people are always more confident than experts in every situation"}, {"id": "d", "text": "The Dunning-Kruger effect describes a mismatch between confidence and competence, though its exact causes remain debated"}]'::jsonb, 3, '{"strategy": "שאלת רעיון מרכזי — הפסקה מציגה את האפקט, ההסבר המקורי לו, ואת הביקורת המחקרית העדכנית עליו.", "correct_reason": "כל הפסקה עוסקת בתיאור האפקט, בהסבר לגביו ובכך שהמחקר העדכני מציג תמונה מורכבת יותר.", "options_analysis": ["הפסקה אומרת ''partly attributable'', לא ''fully explain''", "לא נאמר בפסקה כלל, וגם לא נכון עובדתית", "הכללה שגויה — הפסקה לא טוענת שזה קורה ''תמיד'' בכל מצב", "נכון! אי-התאמה בין ביטחון ליכולת + מחלוקת על הגורמים = הנושא הכולל"]}', 1.06, 2.0, 0.25, 5, 'ai', NULL, true),
('c179452c-01d2-4c5b-965a-9a2e29c223a5', 'reading_comprehension', 'According to the original explanation by Dunning and Kruger, why are less competent people doubly disadvantaged?', '500212bd-ae3f-4c93-b4dd-c83502d7636c', '[{"id": "b", "text": "Because they lack both the competence and the ability to recognize their own incompetence"}, {"id": "d", "text": "Because they receive less education than experts"}, {"id": "a", "text": "Because they are punished more harshly for mistakes"}, {"id": "c", "text": "Because they work in more difficult fields than experts"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את ההסבר המקורי בפסקה.", "correct_reason": "הפסקה אומרת: ''those who lack these skills are doubly disadvantaged, both in their competence and in their capacity to recognize that incompetence''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.56, 2.0, 0.25, 5, 'ai', NULL, true),
('109f1f6e-747c-4083-b960-a176301ab2e9', 'reading_comprehension', 'The word "asymmetry" in the passage most closely means:', '500212bd-ae3f-4c93-b4dd-c83502d7636c', '[{"id": "a", "text": "a scientific method for measuring skill"}, {"id": "c", "text": "a lack of balance or equality between two things"}, {"id": "b", "text": "a type of statistical error"}, {"id": "d", "text": "complete equality between two groups"}]'::jsonb, 1, '{"strategy": "אוצר מילים בהקשר — ''this asymmetry arises because...'' מתייחס לחוסר הסימטריה בין ביטחון ליכולת בין הקבוצות.", "correct_reason": "asymmetry = חוסר סימטריה/איזון בין שני דברים.", "options_analysis": ["לא קשור למשמעות המילה", "נכון! asymmetry = חוסר איזון/סימטריה", "לא קשור ישירות למשמעות המילה עצמה", "הפוך גמור למשמעות המילה"]}', 1.18, 2.0, 0.25, 5, 'ai', NULL, true),
('0bfe2336-2bb3-4923-8264-e7df019f5d68', 'reading_comprehension', 'What has subsequent research suggested about the Dunning-Kruger effect, according to the passage?', '500212bd-ae3f-4c93-b4dd-c83502d7636c', '[{"id": "d", "text": "That it only affects people working in psychology"}, {"id": "b", "text": "That it has been completely disproven and no longer applies"}, {"id": "a", "text": "That it may be partly explained by statistical artifacts rather than being purely psychological"}, {"id": "c", "text": "That confidence and competence are always perfectly correlated"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את הממצא המחקרי המאוחר יותר בפסקה.", "correct_reason": "הפסקה אומרת: ''the effect may be partly attributable to statistical artifacts, such as regression to the mean, rather than a purely psychological phenomenon''.", "options_analysis": ["לא נאמר בפסקה כלל", "סותר את הפסקה — האינטואיציה הבסיסית עדיין מהדהדת", "נכון! נאמר במפורש בפסקה", "הפוך גמור למה שהאפקט טוען"]}', 1.4, 2.0, 0.25, 5, 'ai', NULL, true),
('bf56e0e9-5ce0-406e-9a36-c382819f0319', 'reading_comprehension', 'According to the passage, in what contexts has the Dunning-Kruger effect been invoked?', '500212bd-ae3f-4c93-b4dd-c83502d7636c', '[{"id": "d", "text": "Only in professional sports training"}, {"id": "c", "text": "Exclusively in legal court cases"}, {"id": "b", "text": "Only in academic psychology journals"}, {"id": "a", "text": "Workplace management and political discourse"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את ההקשרים המוזכרים בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''invoked in contexts ranging from workplace management to political discourse''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה כהגבלה כזו", "נכון! נאמר במפורש בפסקה"]}', 1.14, 2.0, 0.25, 5, 'ai', NULL, true),
('9b54b36c-3503-4c80-9c48-bcb93c768267', 'reading_comprehension', 'What is the main idea of the passage?', '41817e81-621b-4990-96c9-891df1c5d053', '[{"id": "d", "text": "The relationship between income inequality and economic growth remains debated and methodologically complex"}, {"id": "a", "text": "Reverse causality has been definitively ruled out by researchers"}, {"id": "c", "text": "Income inequality always accelerates economic growth in every country"}, {"id": "b", "text": "Economists have reached complete consensus on this issue"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה מציגה מספר עמדות מנוגדות ואת המורכבות המתודולוגית של הנושא.", "correct_reason": "כל הפסקה עוסקת בוויכוח בין כלכלנים לגבי הקשר בין אי-שוויון לצמיחה, כולל אי-ודאות סיבתית.", "options_analysis": ["נכון! הוויכוח על הקשר בין אי-שוויון לצמיחה + מורכבות מתודולוגית = הנושא הכולל", "הפוך — הפסקה דווקא מציינת שסיבתיות הפוכה סבירה", "הכללה שגויה וסותרת חלקים אחרים בפסקה", "הפוך — הפסקה מציגה מחלוקת מתמשכת בין כלכלנים"]}', 1.22, 2.0, 0.25, 5, 'ai', NULL, true),
('fe424cd3-701c-4518-bd16-b8473ac526df', 'reading_comprehension', 'According to the passage, how might moderate inequality spur economic growth?', '41817e81-621b-4990-96c9-891df1c5d053', '[{"id": "a", "text": "By eliminating the need for entrepreneurial risk-taking"}, {"id": "c", "text": "By incentivizing innovation and hard work through the prospect of reward"}, {"id": "b", "text": "By restricting access to education for lower-income populations"}, {"id": "d", "text": "By guaranteeing equal outcomes for all citizens"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את הטיעון בעד אי-שוויון מתון בפסקה.", "correct_reason": "הפסקה אומרת: ''moderate inequality can spur growth by incentivizing innovation and hard work, as the prospect of substantial reward motivates individuals to take entrepreneurial risks''.", "options_analysis": ["הפוך — התמריץ דווקא מעודד לקיחת סיכונים יזמיים", "נכון! נאמר במפורש בפסקה", "זה הטיעון של הצד השני, נגד אי-שוויון מוגזם", "לא נאמר בפסקה, וסותר את מושג אי-השוויון"]}', 1.2, 2.0, 0.25, 5, 'ai', NULL, true),
('324f019f-d7ad-492c-a737-3c894eea418e', 'reading_comprehension', 'The word "squandering" in the passage most closely means:', '41817e81-621b-4990-96c9-891df1c5d053', '[{"id": "a", "text": "measuring precisely"}, {"id": "b", "text": "carefully investing"}, {"id": "d", "text": "wasting or failing to use effectively"}, {"id": "c", "text": "significantly increasing"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''squandering human capital that could otherwise contribute productively''.", "correct_reason": "squandering = מבזבז/לא מנצל ביעילות.", "options_analysis": ["לא קשור למשמעות המילה", "הפוך גמור למשמעות המילה", "נכון! squandering = מבזבז/לא מנצל היטב", "לא קשור למשמעות המילה"]}', 1.12, 2.0, 0.25, 5, 'ai', NULL, true),
('f03603f8-5644-4203-987b-b222cc8ecd01', 'reading_comprehension', 'What have cross-country studies generally found, according to the passage?', '41817e81-621b-4990-96c9-891df1c5d053', '[{"id": "d", "text": "No relationship whatsoever between inequality and growth"}, {"id": "c", "text": "A positive correlation between inequality and growth in every country studied"}, {"id": "a", "text": "That inequality only affects developed economies"}, {"id": "b", "text": "A negative correlation between high inequality and sustained growth, especially in developing economies"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את ממצא המחקרים הבין-לאומיים בפסקה.", "correct_reason": "הפסקה אומרת: ''cross-country studies...have generally found a negative correlation between high levels of inequality and sustained growth, particularly in developing economies''.", "options_analysis": ["סותר את הפסקה — נמצא קשר שלילי", "הפוך גמור למה שנמצא במחקרים", "הפוך — ההשפעה בולטת דווקא בכלכלות מתפתחות", "נכון! נאמר במפורש בפסקה"]}', 1.18, 2.0, 0.25, 5, 'ai', NULL, true),
('7d76aebd-5dbb-460d-8a11-d1ab15bf8c5c', 'reading_comprehension', 'What caution do some scholars raise about the correlation between inequality and growth, according to the passage?', '41817e81-621b-4990-96c9-891df1c5d053', '[{"id": "a", "text": "That reverse causality is plausible, since slow growth may itself worsen inequality"}, {"id": "c", "text": "That only developed economies should be studied"}, {"id": "b", "text": "That inequality has no measurable economic effects at all"}, {"id": "d", "text": "That the correlation has been completely disproven"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את האזהרה המתודולוגית בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''reverse causality is plausible: sluggish growth itself may exacerbate inequality''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה, וסותר את ההתמקדות בכלכלות מתפתחות", "סותר את כל הפסקה", "סותר את הפסקה — נמצא מתאם, לא הפרכה מוחלטת"]}', 1.31, 2.0, 0.25, 5, 'ai', NULL, true);